  'dsa.dcsort.inversions': {
    cpp: '#include <iostream>\n#include <vector>\nusing namespace std;vector<long long>a,t;long long go(int lo,int hi){if(hi-lo<2)return 0;int m=(lo+hi)/2;long long c=go(lo,m)+go(m,hi);int i=lo,j=m,k=lo;while(i<m&&j<hi){if(a[i]<=a[j])t[k++]=a[i++];else{c+=m-i;t[k++]=a[j++];}}while(i<m)t[k++]=a[i++];while(j<hi)t[k++]=a[j++];for(k=lo;k<hi;k++)a[k]=t[k];return c;}int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;a.resize(n);t.resize(n);for(auto&x:a)cin>>x;cout<<go(0,n)<<"\\n";}',
    python: 'import sys\ndef go(a):\n    if len(a)<2: return a,0\n    m=len(a)//2\n    L,x=go(a[:m]); R,y=go(a[m:])\n    out=[]; c=x+y; i=j=0; nl=len(L)\n    while i<nl and j<len(R):\n        if L[i]<=R[j]: out.append(L[i]); i+=1\n        else: out.append(R[j]); j+=1; c+=nl-i\n    out+=L[i:]; out+=R[j:]\n    return out,c\nd=sys.stdin.buffer.read().split()\nn=int(d[0])\nprint(go(list(map(int,d[1:1+n])))[1])',
    javascript: 'const d=readInput().trim().split(/\\s+/).map(Number);const n=d[0],a=d.slice(1,1+n),t=new Array(n);function go(lo,hi){if(hi-lo<2)return 0;const m=(lo+hi)>>1;let c=go(lo,m)+go(m,hi),i=lo,j=m,k=lo;while(i<m&&j<hi){if(a[i]<=a[j])t[k++]=a[i++];else{c+=m-i;t[k++]=a[j++];}}while(i<m)t[k++]=a[i++];while(j<hi)t[k++]=a[j++];for(k=lo;k<hi;k++)a[k]=t[k];return c;}console.log(go(0,n));',
    c: '#include <stdio.h>\n#include <stdlib.h>\nlong long *a,*t;long long go(int lo,int hi){if(hi-lo<2)return 0;int m=(lo+hi)/2;long long c=go(lo,m)+go(m,hi);int i=lo,j=m,k=lo;while(i<m&&j<hi){if(a[i]<=a[j])t[k++]=a[i++];else{c+=m-i;t[k++]=a[j++];}}while(i<m)t[k++]=a[i++];while(j<hi)t[k++]=a[j++];for(k=lo;k<hi;k++)a[k]=t[k];return c;}int main(void){int n;scanf("%d",&n);a=malloc(8*n);t=malloc(8*n);for(int i=0;i<n;i++)scanf("%lld",&a[i]);printf("%lld\\n",go(0,n));return 0;}'
  },
